"""26-circle packing: row seeds + fast radius-aware center search + LP radii."""
import numpy as np
import time
from scipy.optimize import linprog, minimize

_DEADLINE = 150.0


def _lp_radii(centers):
    n = len(centers)
    c = -np.ones(n)
    A = []
    b = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A.append(row)
            b.append(d)
    for i in range(n):
        x, y = centers[i]
        row = np.zeros(n)
        row[i] = 1.0
        A.append(row)
        b.append(min(x, y, 1 - x, 1 - y))
    A = np.array(A)
    b = np.array(b)
    res = linprog(c, A_ub=A, b_ub=b, bounds=[(0, None)] * n, method='highs')
    if res.success:
        return np.maximum(res.x, 0.0)
    r = np.array([min(x, y, 1 - x, 1 - y) for x, y in centers])
    for _ in range(500):
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(centers[i, 0] - centers[j, 0],
                             centers[i, 1] - centers[j, 1])
                s = r[i] + r[j]
                if s > d + 1e-12:
                    sc = d / s
                    r[i] *= sc
                    r[j] *= sc
    return r


def _neg_sum(x):
    return -float(np.sum(_lp_radii(x.reshape(-1, 2))))


def _guard(centers, radii):
    n = len(centers)
    radii = radii.copy()
    for i in range(n):
        x, y = centers[i]
        w = min(x, y, 1 - x, 1 - y)
        if radii[i] > w:
            radii[i] = w
    for _ in range(5000):
        ok = True
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(centers[i, 0] - centers[j, 0],
                             centers[i, 1] - centers[j, 1])
                s = radii[i] + radii[j]
                if s > d + 1e-12:
                    ok = False
                    sc = max(d, 0.0) / max(s, 1e-12)
                    radii[i] *= sc
                    radii[j] *= sc
        if ok:
            break
    return np.maximum(radii, 0.0)


def _row_config(config, xlo=0.08, xhi=0.92):
    n = sum(config)
    n_rows = len(config)
    dy = 1.0 / (n_rows + 1)
    centers = np.zeros((n, 2))
    idx = 0
    for rr in range(n_rows):
        k = config[rr]
        y = dy * (rr + 1)
        xs = np.linspace(xlo, xhi, k) if k > 1 else np.array([0.5])
        for x in xs:
            centers[idx] = [x, y]
            idx += 1
    return centers


def _refine(centers, radii):
    """Radius-aware coordinate ascent: nudge a center, recompute LP only if it
    could improve. Accept only strict improvements."""
    centers = centers.copy()
    radii = radii.copy()
    cur = float(np.sum(radii))
    n = len(centers)
    steps = [0.03, 0.015, 0.008]
    for _ in range(50):
        if time.time() > _DEADLINE:
            break
        improved = False
        for i in range(n):
            x, y = centers[i]
            ri = radii[i]
            # candidate neighbor moves (8 dirs + toward corners)
            cands = []
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    if dx == 0 and dy == 0:
                        continue
                    cands.append((x + dx * 0.03, y + dy * 0.03))
            for cx in (0.0, 1.0):
                for cy in (0.0, 1.0):
                    L = np.hypot(cx - x, cy - y)
                    if L > 1e-9:
                        cands.append((x + (cx - x) / L * 0.03, y + (cy - y) / L * 0.03))
            for (nx, ny) in cands:
                if nx < 0.02 or ny < 0.02 or nx > 0.98 or ny > 0.98:
                    continue
                # quick feasibility screen with current radii
                ok = True
                for j in range(n):
                    if j == i:
                        continue
                    d = np.hypot(nx - centers[j, 0], ny - centers[j, 1])
                    if ri + radii[j] > d + 1e-9:
                        ok = False
                        break
                if not ok:
                    continue
                trial = centers.copy()
                trial[i] = [nx, ny]
                tr = _lp_radii(trial)
                val = float(np.sum(tr))
                if val > cur + 1e-9:
                    centers = trial
                    radii = tr
                    cur = val
                    improved = True
                    break
            if improved:
                break
        if not improved:
            break
    return centers, radii, cur


def construct_packing():
    n = 26
    seeds = []
    for cfg in [[5, 5, 5, 5, 5, 1], [4, 5, 5, 5, 5, 2], [3, 5, 5, 5, 5, 3],
                [5, 4, 5, 4, 5, 3], [6, 5, 5, 5, 5], [5, 5, 5, 5, 6],
                [4, 6, 5, 5, 6], [5, 6, 4, 5, 6], [6, 6, 4, 4, 6]]:
        if sum(cfg) == n:
            seeds.append(_row_config(cfg))

    best_centers = None
    best_radii = None
    best_sum = -1.0
    bounds = [(0.02, 0.98)] * (2 * n)
    for seed in seeds:
        if time.time() > _DEADLINE - 40:
            break
        res = minimize(_neg_sum, seed.flatten(), method='L-BFGS-B',
                       bounds=bounds, options={'maxiter': 40, 'ftol': 1e-11})
        centers = res.x.reshape(n, 2)
        radii = _lp_radii(centers)
        centers, radii, s = _refine(centers, radii)
        if s > best_sum:
            best_sum = s
            best_centers = centers.copy()
            best_radii = radii.copy()

    best_radii = _guard(best_centers, best_radii)
    return best_centers, best_radii, float(np.sum(best_radii))

